use vstd::prelude::*;

verus! {
    fn array_to_sequence(arr: &[bool; 10]) -> (res: Vec<bool>)
        ensures
            res.len() == 10,
            forall|k: nat| (k < 10) ==> (res[k as usize] == arr[k as usize])
    {
        let mut res: Vec<bool> = Vec::with_capacity(10);
        let mut idx: usize = 0;

        while idx < 10
            invariant
                idx <= 10,
                res.len() == idx,
                forall|k: nat| (k < idx) ==> (res[k as usize] == arr[k as usize]),
            decreases 10 - idx,
        {
            res.push(arr[idx]);
            idx = idx + 1;
        }

        // After the loop, we assert that the length of res is 10
        assert(res.len() == 10);
        res
    }
}

